// Copies db/migrations/*.sql into src/server/migrations.generated.ts, so the server can apply them at start-up without
// reading files (a standalone build does not ship the .sql files). Runs before every build; the generated file is
// committed, and a test fails if it is out of date.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const dir = path.join(root, "db", "migrations");
const files = fs.readdirSync(dir).filter((name) => name.endsWith(".sql")).sort();
const list = files.map((name) => ({ name, sql: fs.readFileSync(path.join(dir, name), "utf8") }));
const out =
  "// GENERATED by scripts/gen-migrations.mjs from db/migrations/*.sql. Do not edit by hand.\n\n" +
  "export const MIGRATIONS: { name: string; sql: string }[] = " + JSON.stringify(list, null, 2) + ";\n";
const target = path.join(root, "src", "server", "migrations.generated.ts");
if (!fs.existsSync(target) || fs.readFileSync(target, "utf8") !== out) fs.writeFileSync(target, out);
